package umbrix.core.plugin

import java.util.concurrent.{CompletableFuture, ConcurrentHashMap}
import scala.jdk.CollectionConverters.*
import umbrix.core.session.LogSession

/**
 * Diagnostic findings and summary generated by an AsyncLogAnalyzer.
 */
case class AnalysisReport(
  analyzerId: String,
  analyzerName: String,
  summary: String,
  findingsCount: Int,
  executionDurationMs: Long,
  attributes: Map[String, String] = Map.empty
)

/**
 * Service Provider Interface (SPI) for asynchronous log analyzers and plugins.
 *
 * Allows background plugins (such as GC log analyzers, heap dump inspectors, latency stall detectors)
 * to hook into the off-heap LogSession without blocking the UI thread or 64-bit viewport rendering.
 */
trait AsyncLogAnalyzer {
  def id: String
  def displayName: String
  def description: String

  def isApplicable(session: LogSession): Boolean

  def analyzeAsync(
    session: LogSession,
    onProgress: java.util.function.DoubleConsumer
  ): CompletableFuture[AnalysisReport]
}

/**
 * Central registry for active workstation analysis plugins.
 */
object PluginRegistry {

  private val RegisteredPlugins = new ConcurrentHashMap[String, AsyncLogAnalyzer]()

  def register(plugin: AsyncLogAnalyzer): Unit = {
    RegisteredPlugins.put(plugin.id, plugin)
  }

  def unregister(pluginId: String): Unit = {
    RegisteredPlugins.remove(pluginId)
  }

  def allPlugins: List[AsyncLogAnalyzer] = {
    RegisteredPlugins.values().asScala.toList
  }

  def get(pluginId: String): Option[AsyncLogAnalyzer] = {
    Option(RegisteredPlugins.get(pluginId))
  }

  def pluginManager: PluginManager = PluginManager.instance
}
